// «Подтверждение сразу на экране»: блок-квитанция после отправки записи — услуга, дата и время
// крупным планом, с пометкой о подтверждении (catalog D1 confirm receipt). Композиция по мотивам
// HyperUI «Receipt» (MIT, © Mark Mead), переписана на токенах дизайн-системы.
import { LazyMotion, domAnimation, m, useReducedMotion } from 'motion/react';

type Link = { label: string; href: string };

export type BookingConfirmationReceiptProps = {
  title: string;
  serviceLabel: string;
  service: string;
  dateLabel: string;
  date: string;
  timeLabel: string;
  time: string;
  note: string;
  extra?: string;
  accountAction: Link;
  secondaryAction?: Link;
};

export default function BookingConfirmationReceipt({
  title,
  serviceLabel,
  service,
  dateLabel,
  date,
  timeLabel,
  time,
  note,
  extra,
  accountAction,
  secondaryAction,
}: BookingConfirmationReceiptProps) {
  const prefersReduced = useReducedMotion();

  const rows = [
    { label: serviceLabel, value: service, big: false },
    { label: dateLabel, value: date, big: true },
    { label: timeLabel, value: time, big: true },
  ];

  return (
    <LazyMotion features={domAnimation}>
      <section aria-labelledby="booking-receipt-title" className="bg-muted font-sans text-foreground">
        <div className="mx-auto w-full max-w-page px-gutter py-section">
          <m.div
            initial={prefersReduced ? false : { opacity: 0, y: 12 }}
            animate={prefersReduced ? undefined : { opacity: 1, y: 0 }}
            transition={{ duration: 0.4, ease: 'easeOut' }}
            className="mx-auto max-w-text min-w-0 rounded-lg border border-border bg-card text-card-foreground shadow-sm"
          >
            <div className="border-b border-dashed border-border px-6 py-8 sm:px-8">
              <h2 id="booking-receipt-title" className="font-display text-h2 font-bold text-balance wrap-break-word">
                {title}
              </h2>
            </div>

            <dl className="divide-y divide-border">
              {rows.map((row) => (
                <div
                  key={row.label}
                  className="flex flex-wrap items-baseline justify-between gap-x-6 gap-y-1 px-6 py-5 sm:px-8"
                >
                  <dt className="text-body text-muted-foreground">{row.label}</dt>
                  <dd
                    className={
                      row.big
                        ? 'min-w-0 text-right font-display text-h2 font-bold wrap-break-word'
                        : 'min-w-0 text-right text-body font-semibold wrap-break-word'
                    }
                  >
                    {row.value}
                  </dd>
                </div>
              ))}
            </dl>

            <div className="border-t border-dashed border-border px-6 py-6 sm:px-8">
              <p className="text-small text-muted-foreground">{note}</p>
              {extra ? <p className="mt-1 text-small text-muted-foreground">{extra}</p> : null}
            </div>
          </m.div>

          <div className="mx-auto mt-8 flex max-w-text flex-col items-stretch gap-3 sm:flex-row sm:justify-center">
            <a
              href={accountAction.href}
              className="inline-flex min-h-11 items-center justify-center rounded-control bg-primary px-6 text-center text-body font-bold text-primary-foreground transition-opacity duration-200 hover:opacity-90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-foreground"
            >
              {accountAction.label}
            </a>
            {secondaryAction ? (
              <a
                href={secondaryAction.href}
                className="inline-flex min-h-11 items-center justify-center rounded-control border border-border bg-card px-6 text-center text-body font-bold text-foreground transition-colors duration-200 hover:bg-muted focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-foreground"
              >
                {secondaryAction.label}
              </a>
            ) : null}
          </div>
        </div>
      </section>
    </LazyMotion>
  );
}

